package com.bank.narration;

import java.util.*;
import java.util.logging.*;

public class NarrationDemo {
    private static final Logger log = Logger.getLogger("Narration");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> narrations = List.of(
            "SALARY CREDIT", "RENT DEBIT", "SALARY CREDIT",
            "SALARY ARREAR", "RENT DEBIT");
        NarrationAnalyzer analyzer = new NarrationAnalyzer();

        Map<String, Long> freq = analyzer.wordFrequency(narrations);
        log.info(() -> "Frequency: " + freq);

        List<Map.Entry<String, Long>> top = analyzer.topWords(narrations, 2);
        top.forEach(e -> log.info(() -> "  " + e.getKey() + " = " + e.getValue()));
    }
}

// ─── Would be in service/NarrationAnalyzer.java ───
class NarrationAnalyzer {
    // split each narration into words, count occurrences per word
    Map<String, Long> wordFrequency(List<String> narrations) {
        return narrations.stream()
            .flatMap(n -> java.util.Arrays.stream(n.split("\\s+")))   // words
            .collect(java.util.stream.Collectors.groupingBy(
                w -> w, java.util.stream.Collectors.counting()));
    }

    // rank words by count descending, tie-break by word, take top N
    List<Map.Entry<String, Long>> topWords(List<String> narrations, int topN) {
        return wordFrequency(narrations).entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue(Comparator.reverseOrder())
                .thenComparing(Map.Entry.comparingByKey()))
            .limit(topN)
            .collect(java.util.stream.Collectors.toList());
    }
}
